args.content:
$out = "C:\Users\trex2\AppData\Local\Temp\opencode\pass7"
$t = Get-Content "E:\Potential-gold\PluseOPS\output\autter\guided.md" -Raw
$res = @()

$labels = @(
 'Live Site Security','Archaeology','SBOM','Secrets','Dependencies','Licenses','SAST','Config',
 'Exploits','Containers','IaC','API Surface','Supply Chain','Legacy','Policy','AI Slop',
 'Exploit Chains','Database','Code Quality','Frontend Health','Code Hygiene','Boot Runtime',
 'Business Logic','Payments','AI Attribution','LLM Security','RLS Security','UI Slop','TODOs'
)
$res += "Label list I built = $($labels.Count) entries"

# anchor at 'All findings (4)' then consume labels in order
$anchor = 'All findings \(4\)'
$rx = [regex]::new('\G\s*(' + (($labels | ForEach-Object { [regex]::Escape($_) }) -join '|') + ')')

$counts = @{}
$bars = 0
foreach ($am in [regex]::Matches($t, $anchor)) {
  $pos = $am.Index + $am.Length
  $seen = @()
  for ($k=0; $k -lt 60; $k++) {
    $m = [regex]::Match($t, '\G\s*(' + (($labels | ForEach-Object { [regex]::Escape($_) }) -join '|') + ')', $pos)
    if (-not $m.Success) { break }
    $seen += $m.Groups[1].Value
    $pos = $m.Index + $m.Length
  }
  if ($seen.Count -gt 0) {
    $bars++
    $key = [string]$seen.Count
    if ($counts.ContainsKey($key)) { $counts[$key]++ } else { $counts[$key] = 1 }
  }
}

$res += "tab bars parsed = $bars"
$res += "tab-count -> occurrences histogram:"
foreach ($k in ($counts.Keys | Sort-Object { [int]$_ })) { $res += "   $k tabs : $($counts[$k]) times" }
$res += "TOTAL TABS after 'All findings (4)' = $($labels.Count)"
$res | Out-File (Join-Path $out 'tabs2.txt') -Encoding utf8
Get-Content (Join-Path $out 'tabs2.txt')

$out = "C:\Users\trex2\AppData\Local\Temp\opencode\pass7"
$t = Get-Content "E:\Potential-gold\PluseOPS\output\autter\guided.md" -Raw
$res = @()

$ms = [regex]::Matches($t, '(.{0,300})was skipped for this scan')
$names = [ordered]@{}
foreach ($m in $ms) {
  $pre = $m.Groups[1].Value
  # the panel usually ends with the agent title then this line
  $nm = ($pre -split ' ' | Where-Object { $_ -ne '' })[-1]
  if ($names.Contains($nm)) { $names[$nm] = $names[$nm] + 1 } else { $names[$nm] = 1 }
}
$res += "occurrences = $($ms.Count)"
$res += "distinct preceding tokens = $($names.Count)"
foreach ($k in $names.Keys) { $res += ("   '{0}' x{1}" -f $k, $names[$k]) }

$res += ""
$res += "=== 3 wider raw windows ==="
for ($i=0; $i -lt 3; $i++) { $res += ("  [" + $ms[$i].Groups[1].Value + "]"); $res += "" }

$res += "=== Loading occurrences ==="
$lm = [regex]::Matches($t, 'Loading.{0,60}')
$res += "count = $($lm.Count)"
foreach ($m in $lm) { $res += "   " + $m.Value }

$res | Out-File (Join-Path $out 'skip2.txt') -Encoding utf8
Get-Content (Join-Path $out 'skip2.txt')

$out = "C:\Users\trex2\AppData\Local\Temp\opencode\pass7"
$caps = @(
 'E:\Potential-gold\PluseOPS\output\autter\guided.md',
 'E:\Potential-gold\PluseOPS\output\autter\observations.md',
 'E:\Potential-gold\PluseOPS\output\autter\cli-capture.md',
 'E:\Potential-gold\PluseOPS\output\autter\actions.json',
 'E:\Potential-gold\PluseOPS\output\autter\assignment.md'
)
$res = @()
$patterns = @('occurrences','placeholder','in test files','still active','in git history','verified','test:day72','day72')
foreach ($p in $patterns) {
  $res += "--- case-insensitive: '$p'"
  foreach ($f in $caps) {
    $t = Get-Content $f -Raw
    $ms = [regex]::Matches($t, $p, 'IgnoreCase')
    if ($ms.Count -gt 0) {
      $res += ("     {0} -> {1}" -f (Split-Path $f -Leaf), $ms.Count)
      foreach ($m in ($ms | Select-Object -First 3)) {
        $s = [Math]::Max(0, $m.Index-140); $len = [Math]::Min(300, $t.Length-$s)
        $res += ("        ..." + ($t.Substring($s,$len) -replace '\s+',' ') + "...")
      }
    }
  }
}
$res | Out-File (Join-Path $out 'pats2.txt') -Encoding utf8
Get-Content (Join-Path $out 'pats2.txt')

$out = "C:\Users\trex2\AppData\Local\Temp\opencode\pass7"
$gt = Get-Content "E:\Potential-gold\PluseOPS\output\autter\guided.md" -Raw
$res = @()

# The "Clickable here:" line on a scan page enumerates the tab strip as clickable elements
$m = [regex]::Match($gt, 'Share, Overview, All findings \(4\)([^V]*)TODOs')
if ($m.Success) {
  $seg = $m.Value -replace '.*Share, ',''
  $res += "CLICKABLE TAB STRIP (verbatim):"
  $res += "  $seg"
  $parts = ($seg -split ',') | ForEach-Object { $_.Trim() } | Where-Object { $_ -ne '' }
  $res += "tab elements in strip = $($parts.Count)"
  for ($i=0; $i -lt $parts.Count; $i++) { $res += ("   {0,2}. {1}" -f ($i+1), $parts[$i]) }
} else { $res += "clickable strip regex did not match" }

$res | Out-File (Join-Path $out 'strip.txt') -Encoding utf8
Get-Content (Join-Path $out 'strip.txt')

